import{_ as a,o as t,c as s,a0 as o}from"./chunks/framework.ZC3WYqLu.js";const r="/cass-editor/docs/assets/user-configuration.B_80Vb5p.png",n="/cass-editor/docs/assets/manage-default-owners.C87xSNN9.png",i="/cass-editor/docs/assets/select-default-owners.BLqG0548.png",d="/cass-editor/docs/assets/manage-default-readers.Dp63xXGj.png",l="/cass-editor/docs/assets/select-default-readers.CZoC8sEb.png",b=JSON.parse('{"title":"Managing Default Users","description":"","frontmatter":{},"headers":[],"relativePath":"authoring/default-users/index.md","filePath":"authoring/default-users/README.md"}'),c={name:"authoring/default-users/index.md"};function u(m,e,g,p,f,h){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="managing-default-users" tabindex="-1">Managing Default Users <a class="header-anchor" href="#managing-default-users" aria-label="Permalink to &quot;Managing Default Users&quot;">​</a></h1><p>By default, the creator of a CaSS framework, competency, or other object is assigned as the sole owner of that record. By using the <em><strong>user configuration</strong></em> section of the configuration, other specified users and groups can be assigned as owners and readers to objects created in the framework/competency editor that use the configuration.</p><p><img src="'+r+'" alt="User configuration"></p><h2 id="default-owners" tabindex="-1">Default Owners <a class="header-anchor" href="#default-owners" aria-label="Permalink to &quot;Default Owners&quot;">​</a></h2><p>Users and groups added to this section are automatically added to the owner list of any object created in the framework/competency editor that use this configuration. To manage the list of default owners, click the <em><strong>manage default owners</strong></em> button in the <em><strong>default owners</strong></em> section.</p><p><img src="'+n+'" alt="Manage Default Owners"></p><p>Once clicked, the <em><strong>select default owners</strong></em> dialogue window is displayed. Select the desired default owner entries and click the <em><strong>apply</strong></em> button in the bottom right of the dialogue window. Default owners can also be removed in a similar fashion.</p><p><img src="'+i+'" alt="Select Default Owners"></p><div class="tip custom-block"><p class="custom-block-title">Note</p><p>Users and groups can be differentiated by the type column icon and email address. All assignable users will have an email address and single person icon. All group assignable groups will display <em>&quot;n/a&quot;</em> for an email address and a multi person icon.</p></div><h2 id="default-readers" tabindex="-1">Default Readers <a class="header-anchor" href="#default-readers" aria-label="Permalink to &quot;Default Readers&quot;">​</a></h2><p>Users and groups added to this section are automatically added to the reader list of any object created in the framework/competency editor that use this configuration. To manage the list of default owners, click the <em><strong>manage default owners</strong></em> button in the <em><strong>default owners</strong></em> section.</p><p><img src="'+d+'" alt="Manage Default Readers"></p><p>Once clicked, the <em><strong>select default readers</strong></em> dialogue window is displayed. Select the desired default reader entries and click the <em><strong>apply</strong></em> button in the bottom right of the dialogue window. Note: Default readers can also be removed in a similar fashion.</p><p><img src="'+l+'" alt="Select Default Readers"></p><div class="tip custom-block"><p class="custom-block-title">Note</p><p>Users and groups can be differentiated by the type column icon and email address. All assignable users will have an email address and single person icon. All group assignable groups will display <em>&quot;n/a&quot;</em> for an email address and a multi person icon.</p></div>',15)])])}const _=a(c,[["render",u]]);export{b as __pageData,_ as default};
